import { Icon } from 'antd'
import FilterText from './filterText'

export const ColumnSearchProps = (props, key, type) => {
  return {
    filterDropdown: ({ setSelectedKeys, selectedKeys }) => (
      <div className='filter-dropdown'>
        {renderSearchProps(props, type, key, setSelectedKeys, selectedKeys)}
      </div >
    ),
    filterIcon: () => <Icon type='filter' />,
    onFilter: (value, record) =>
      record[key]
        ? record[key].toString().toLowerCase().includes(value.toLowerCase())
        : '',
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => props.searchInput && props.searchInput.select(), 100)
      }
    }
  }
}

const renderSearchProps = (props, type, key, setSelectedKeys, selectedKeys) => {
    return <FilterText
    props={props}
    type={type}
    searchKey={key}
    setSelectedKeys={setSelectedKeys}
    selectedKeys={selectedKeys}
  />

}
