import React from 'react'
import { Alert } from 'antd'

const failedFetchData = ({ isNeedDisplay, onClose = () => {}, status, message }) => {
  if (isNeedDisplay) {
    return (
      <Alert
        style={{ marginBottom: '10px', padding: '10px 50px 8px 10px' }}
        message={message}
        type={status}
        closeText='Close'
        onClose={onClose}
      />
    )
  } else {
    return ''
  }
}

export default failedFetchData
